let SCEN_A_MAP = null;
function scenA(a) {
  if (XL.v !== "en") return a;
  if (!SCEN_A_MAP) { SCEN_A_MAP = Object.assign({}, SCEN_A_EN); SCENARIOS.forEach(s => { if (s.aEn) SCEN_A_MAP[s.a] = s.aEn; }); }
  return SCEN_A_MAP[a] || a;
}

// ===== シナリオ問題 =====
function Scenario({ t }) {
  const [filter, setFilter] = useState("ALL");
  const [picked, setPicked] = useState({});
  const [open, setOpen] = useState({});
  const [cur, setCur] = useState(0);

  const list = SCENARIOS.filter(s => {
    if (filter === "ALL") return true;
    if (filter === "scenario" || filter === "calc") return s.type === filter;
    return s.d === filter;
  });
  const typeLabel = (ty) => ty === "calc" ? t.typeCalc : t.typeScenario;

  // 他資格と体裁を揃える：シナリオ型は4択（誤答は同ドメインの実在サービス/手法から生成）。
  const poolAll = [...new Set(SCENARIOS.filter(s => s.type !== "calc").map(s => s.a))];
  const buildOptions = (s) => {
    const correct = s.a;
    const domCand = [...new Set(SCENARIOS.filter(x => x.type !== "calc" && x.d === s.d && x.a !== correct).map(x => x.a))];
    const cand = [...domCand, ...poolAll.filter(a => a !== correct && !domCand.includes(a))];
    const seed = [...s.id].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 100000, 7);
    const picks = [];
    let idx = seed % Math.max(1, cand.length), guard = 0;
    while (picks.length < 3 && picks.length < cand.length && guard < 100) {
      const c = cand[idx % cand.length];
      if (!picks.includes(c)) picks.push(c);
      idx += 1 + (seed % 5); guard++;
    }
    const opts = [correct, ...picks];
    for (let i = opts.length - 1; i > 0; i--) { const j = (seed + i * 7) % (i + 1); const tmp = opts[i]; opts[i] = opts[j]; opts[j] = tmp; }
    return { opts, ans: opts.indexOf(correct) };
  };

  const head = (s) => (
    <div style={{ display: "flex", gap: 6, alignItems: "center", marginBottom: 8, flexWrap: "wrap" }}>
      <span style={{ background: C.deep, color: nvInk("#ffffff", C.deep), borderRadius: 4, padding: "1px 7px", fontSize: 11, fontWeight: 700 }}>{s.id}</span>
      <span style={{ background: s.type === "calc" ? "#3BB8D4" : DOM_HUE[s.d], color: nvInk("#ffffff", s.type === "calc" ? "#3BB8D4" : DOM_HUE[s.d]), borderRadius: 4, padding: "1px 7px", fontSize: 10.5 }}>{typeLabel(s.type)}</span>
      <span style={{ fontSize: 11, color: "#53757f" }}>{s.d} · {domName(s.d)}</span>
    </div>
  );

  return (
    <div>
      <Card title={t.scenarioTitle}>
        <div style={{ fontSize: 13, lineHeight: 1.6, color: "#476770" }}>{t.scenarioDesc}</div>
        <div style={{ fontSize: 12, color: "#53757f", marginTop: 6 }}>{t.scenarioCount(SCENARIOS.length)}</div>
      </Card>

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        {["ALL", "scenario", "calc", ...DOMAINS.map(d => d.id)].map(k => {
          const label = k === "ALL" ? t.allFields : k === "scenario" ? t.typeScenario : k === "calc" ? t.typeCalc : k;
          return (
            <button key={k} onClick={() => { setFilter(k); setCur(0); }}
              style={{
                padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer",
                border: `1px solid ${filter === k ? C.primary : C.mid}`,
                background: filter === k ? C.primary : "#fff", color: filter === k ? nvInk("#ffffff", C.primary) : nvInk(C.ink, "#ffffff"), fontWeight: 600,
              }}>
              {label}
            </button>
          );
        })}
      </div>

      {(() => {
        const idx = Math.min(cur, Math.max(0, list.length - 1));
        const s = list[idx];
        if (!s) return <div style={{ fontSize: 13, color: "#53757f" }}>{t.noMatch}</div>;
        const card = (() => {
          if (s.type === "calc") {
            const isOpen = open[s.id];
            return (
              <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 11, padding: 14 }}>
                {head(s)}
                <div style={{ fontSize: 14, fontWeight: 600, lineHeight: 1.55, marginBottom: 10 }}>{Lx(s, "q")}</div>
                {!isOpen ? (
                  <button onClick={() => setOpen(o => ({ ...o, [s.id]: true }))}
                    style={{ padding: "8px 16px", borderRadius: 8, border: `1.5px solid ${C.primary}`, background: "#fff", color: nvInk(C.primary, "#ffffff"), fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
                    {t.showAnswer}
                  </button>
                ) : (
                  <div style={{ background: C.light, borderRadius: 9, padding: 12 }}>
                    <div style={{ fontSize: 14, fontWeight: 700, color: C.deep, marginBottom: 5 }}>{scenA(s.a)}</div>
                    <div style={{ fontSize: 13, lineHeight: 1.55, color: "#476770" }}>{Lx(s, "e")}</div>
                  </div>
                )}
              </div>
            );
          }
          const { opts, ans } = buildOptions(s);
          const sel = picked[s.id];
          return (
            <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 11, padding: 14 }}>
              {head(s)}
              <div style={{ fontSize: 14, fontWeight: 600, lineHeight: 1.55, marginBottom: 10 }}>{Lx(s, "q")}</div>
              {opts.map((o, i) => {
                let bg = "#fff", bd = C.mid, col = C.ink;
                if (sel != null) { if (i === ans) { bg = "#E6F4EF"; bd = C.ok; col = C.ok; } else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; } }
                return (
                  <button key={i} onClick={() => { if (sel == null) setPicked(p => ({ ...p, [s.id]: i })); }} disabled={sel != null}
                    style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 7, padding: "10px 12px", borderRadius: 8, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel == null ? "pointer" : "default", fontSize: 13, lineHeight: 1.5, fontWeight: sel != null && i === ans ? 700 : 500 }}>
                    <span style={{ fontWeight: 700, marginRight: 8 }}>{sel != null && i === ans ? "✓" : sel != null && i === sel ? "✗" : "ABCDE"[i]}</span>{scenA(o)}
                  </button>
                );
              })}
              {sel != null && (
                <div style={{ background: C.light, borderRadius: 9, padding: 12, marginTop: 4 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: sel === ans ? C.ok : C.ng, marginBottom: 5 }}>{sel === ans ? t.correct : t.incorrect}{t.sepDot}{scenA(s.a)}</div>
                  <div style={{ fontSize: 13, lineHeight: 1.55, color: "#476770" }}>{Lx(s, "e")}</div>
                </div>
              )}
            </div>
          );
        })();
        return (
          <div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8, fontSize: 12.5, color: "#5a7780" }}>
              <span>{typeLabel(s.type)} · {s.d}</span>
              <span>{idx + 1} / {list.length}</span>
            </div>
            {card}
            <div style={{ display: "flex", gap: 10, marginTop: 12 }}>
              <button onClick={() => setCur(c => Math.max(0, c - 1))} disabled={idx === 0}
                style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: idx === 0 ? "#a8c2cc" : C.deep, fontSize: 14, fontWeight: 700, cursor: idx === 0 ? "default" : "pointer" }}>{t.prevQ}</button>
              <button onClick={() => setCur(c => Math.min(list.length - 1, c + 1))} disabled={idx >= list.length - 1}
                style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: idx >= list.length - 1 ? C.mid : C.primary, color: nvInk("#ffffff", idx >= list.length - 1 ? C.mid : C.primary, 3), fontSize: 14, fontWeight: 700, cursor: idx >= list.length - 1 ? "default" : "pointer" }}>{t.nextQ}</button>
            </div>
          </div>
        );
      })()}
    </div>
  );
}
// ===== 比較表 =====
function Compare({ t }) {
  const [idx, setIdx] = useState(0);
  const table = COMPARE[idx];
  return (
    <div>
      <div style={{ fontSize: 12, color: "#53757f", marginBottom: 10 }}>{t.compareIntro}</div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 14 }}>
        {COMPARE.map((c, i) => (
          <button key={i} onClick={() => setIdx(i)}
            style={{
              padding: "6px 11px", borderRadius: 16, fontSize: 11.5, cursor: "pointer",
              border: `1px solid ${idx === i ? C.primary : C.mid}`,
              background: idx === i ? C.primary : "#fff", color: idx === i ? nvInk("#ffffff", C.primary) : nvInk(C.ink, "#ffffff"), fontWeight: 600,
            }}>
            {Lx(c, "title")}
          </button>
        ))}
      </div>

      <CmpOne c={{ title: table.title, titleEn: Lx(table, "title"), axisJa: (table.headers || [])[0], axisEn: (Lx(table, "headers") || [])[0], cols: (table.headers || []).slice(1), colsEn: (Lx(table, "headers") || []).slice(1), rows: table.rows, rowsEn: Lx(table, "rows") || table.rows }} C={C} en={XL.v === "en"} />

      <div style={{ display: "flex", justifyContent: "space-between", marginTop: 12 }}>
        <button onClick={() => setIdx(i => (i - 1 + COMPARE.length) % COMPARE.length)}
          style={{ padding: "9px 16px", borderRadius: 8, border: `1.5px solid ${C.primary}`, background: "#fff", color: nvInk(C.primary, "#ffffff"), fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
          {t.prevShort}
        </button>
        <span style={{ fontSize: 12, color: "#53757f", alignSelf: "center" }}>{idx + 1} / {COMPARE.length}</span>
        <button onClick={() => setIdx(i => (i + 1) % COMPARE.length)}
          style={{ padding: "9px 16px", borderRadius: 8, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary), fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
          {t.nextShort}
        </button>
      </div>
    </div>
  );
}

